const body = $input.first().json.body || $input.first().json;

const username = body.username || 'Unknown Player';
const score = body.score ?? 0;
const isFlagged = body.is_flagged ?? 0;
const reason = body.reason || 'Telemetry Anomaly Detected';
const hardwareProfile = body.hardwareProfile || 'Unknown Hardware ID';
const telemetry = body.telemetrySummary || {};
const timestamp = new Date().toISOString();

// Calculate multiplier / velocity anomaly ratio
const inputVelocity = telemetry.inputVelocity || 0;
const anomalyMultiplier = (inputVelocity > 15 ? (inputVelocity / 15).toFixed(2) : '1.00') + 'x norm';

return {
  username,
  score,
  isFlagged,
  reason,
  hardwareProfile,
  telemetry,
  anomalyMultiplier,
  timestamp
};

